import React from 'react';

import Details from '../komponen/Details';


function Abouts(props) {

    return(
        <div
            className="d-inline-block g-card"
            onClick={(e) => props.click(props.item)}>

            { props.item.pilih &&
              <Details title={props.arr.nama}
                        subTitle={props.arr.sub}
               />
            }

        </div>
    );

}

export default Abouts;

